<?php require __DIR__.'/config/bootstrap.php'; $page_title='Services · '.site_setting('company_name'); require __DIR__.'/includes/header.php'; $items=db_rows('SELECT * FROM services WHERE active=1 ORDER BY sort_order,id'); ?><section class="page-hero"><div class="container"><span class="eyebrow">Our capabilities</span><h1>Services</h1><p>Surveying, drafting and technical support for land, buildings, roads and development projects.</p></div></section><section class="section"><div class="container"><div class="grid-3"><?php if(!$items): ?><p class="empty-state">No services are published yet. Add them in <strong>Admin &rarr; Services</strong>.</p><?php endif; ?><?php foreach($items as $s): ?><article class="service-card"><div class="service-icon"><i class="<?=e($s['icon'])?>"></i></div><h3><?=e($s['title'])?></h3><p><?=e($s['short_text'])?></p><p><?=nl2br(e($s['description']))?></p></article><?php endforeach;?></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>